#include <stdint.h>
int main(void)
{
	volatile uint32_t *pClockContrlReg = (uint32_t*)  0x40023830;
	uint32_t *pGPIOAmodeReg = (uint32_t*) 0x40020000;
	uint32_t *pOPdataReg = (uint32_t*) 0x40020014;
//	1. Enable the clock in peripheral A in RCC_AHB1ENR
	*pClockContrlReg |= (1 << 0);
//	2. Configure the mode as GPIOA pin as OUTPUT
//	a. Clear the 10th and 11th bit position (CLEAR)
	*pGPIOAmodeReg &= ~(3 << 10);
//	b. Make 10 bit position as 1 (SET)
	*pGPIOAmodeReg |= (1 << 10);

	while(1)
	{
	//	3. SET 5 bit of the output data register to make I/O pin-5 HIGH
		*pOPdataReg |= (1 << 5);
	//	Introducing the Human Observable Delay
		for(uint32_t i = 0; i <= 1000000 ; i++);
	//	Turn off the LED
		*pOPdataReg &= ~(1 << 5);
	//	Again Introducing Delay
		for(uint32_t i=0; i<= 100000 ; i++);
	}
}




